-- Distribuidores
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D1'), 'Lácteos Cerro Pelado', 'Empresa familiar fundada en 1994 por los hermanos Gustavo y Daniel Ramírez. Distribuimos lácteos, quesos y fiambres a almacenes, autoservicios y cantinas de la ciudad de Maldonado, con cadena de frío propia. Repartimos de lunes a sábado en la mañana.', 'Maldonado Centro, Cerro Pelado, Maldonado Nuevo, San Fernando y Villa Delia', 'Cerro Pelado, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '190 days' + TIME '11:00', '/uploads/demo/logos/lacteos-cerro-pelado.svg', -34.8725834, -54.9810789) RETURNING id) INSERT INTO _seed_ids SELECT 'D1', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D2'), 'Carnes San Carlos', 'Más de 30 años abasteciendo a carnicerías, rotiserías y parrillas de San Carlos y Maldonado. Cortes vacunos, cerdo, pollo y chacinados con trazabilidad y entrega refrigerada. Reparto martes, jueves y sábados.', 'San Carlos, Maldonado Nuevo, San Fernando y La Barra', 'Treinta y Tres, San Carlos, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '194 days' + TIME '11:00', '/uploads/demo/logos/carnes-san-carlos.svg', -34.7913985, -54.9251846) RETURNING id) INSERT INTO _seed_ids SELECT 'D2', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D3'), 'Frutihortícola Pan de Azúcar', 'Trabajamos directo con productores de Pan de Azúcar y de las chacras de San Carlos. Frutas y verduras de estación para fruterías, almacenes y comedores, seleccionadas cada madrugada. Entregas de lunes a viernes antes del mediodía.', 'Pan de Azúcar, Piriápolis, Playa Hermosa y Playa Verde', 'Libertador Juan Antonio Lavalleja, Pan de Azúcar, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '192 days' + TIME '11:00', '/uploads/demo/logos/frutihorticola-pan-de-azucar.svg', -34.774672, -55.2248698) RETURNING id) INSERT INTO _seed_ids SELECT 'D3', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D4'), 'Panificadora La Carolina', 'Panadería de barrio desde 1987 que hoy abastece a almacenes, cafeterías y kioscos de San Carlos y Maldonado. Pan del día, bizcochos, galletería y panificados envasados. Reparto diario, también los domingos de mañana.', 'San Carlos, Maldonado Centro, Cerro Pelado y Villa Delia', '25 de Agosto, San Carlos, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '189 days' + TIME '11:00', '/uploads/demo/logos/panificadora-la-carolina.svg', -34.7902102, -54.92868) RETURNING id) INSERT INTO _seed_ids SELECT 'D4', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D5'), 'Bebidas La Barra', 'Distribuidor de bebidas con y sin alcohol para comercios, restoranes y paradores de Punta del Este y la costa este. Aguas, refrescos, cervezas, vinos y jugos con entrega en cajones y packs cerrados. Reparto de lunes a sábado, y todos los días en temporada.', 'Punta del Este, San Rafael, La Barra, Manantiales y José Ignacio', 'Ruta 10, La Barra, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '156 days' + TIME '11:00', '/uploads/demo/logos/bebidas-la-barra.svg', -34.9086018, -54.8399854) RETURNING id) INSERT INTO _seed_ids SELECT 'D5', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D6'), 'Limpieza Fernandina', 'Desde 2005 abastecemos a comercios, oficinas e instituciones de todo el departamento de Maldonado con artículos de limpieza e higiene. Marcas reconocidas y formatos institucionales a precio mayorista. Reparto martes y viernes.', 'Maldonado, San Carlos, Pan de Azúcar y Piriápolis', 'Ruta 39, Barrio Perlita, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '197 days' + TIME '11:00', '/uploads/demo/logos/limpieza-fernandina.svg', -34.8884024, -54.9523569) RETURNING id) INSERT INTO _seed_ids SELECT 'D6', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D7'), 'Almacenera Maldonado', 'Distribuidora de almacén con más de 25 años en el centro de Maldonado. Conservas, enlatados, secos y aceites para almacenes, rotiserías y comedores, con precios especiales por cantidad. Reparto lunes, miércoles y viernes.', 'Maldonado Centro, Sarubbi, Las Delicias, San Fernando y Punta del Este', '18 de Julio, Barrio Centro, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '162 days' + TIME '11:00', '/uploads/demo/logos/almacenera-maldonado.svg', -34.9091326, -54.9587107) RETURNING id) INSERT INTO _seed_ids SELECT 'D7', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D8'), 'Congelados Punta del Este', 'Especialistas en congelados para comercios y gastronomía de Punta del Este. Hamburguesas, papas, vegetales, pescados y helados con flota refrigerada propia. Pedidos hasta las 18 h para entrega al día siguiente.', 'Punta del Este, San Rafael, Punta Ballena, La Barra y Maldonado', 'Avenida Italia, San Rafael, Punta del Este', true, date_trunc('day', NOW()) - INTERVAL '198 days' + TIME '11:00', '/uploads/demo/logos/congelados-punta-del-este.svg', -34.9438388, -54.9325118) RETURNING id) INSERT INTO _seed_ids SELECT 'D8', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D9'), 'Mayorista San Fernando', 'Mayorista de almacén general con depósito en Maldonado Nuevo. Surtido completo de alimentos, bebidas, limpieza y perfumería para autoservicios y almacenes de barrio. Reparto de lunes a sábado.', 'Maldonado Nuevo, San Fernando, Las Delicias, Sarubbi y Cerro Pelado', 'Maldonado Nuevo, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '159 days' + TIME '11:00', '/uploads/demo/logos/mayorista-san-fernando.svg', -34.8945284, -54.9395118) RETURNING id) INSERT INTO _seed_ids SELECT 'D9', id FROM n;
WITH n AS (INSERT INTO distribuidor (usuario_id, nombre_comercial, descripcion_negocio, zona_entrega, direccion_partida, perfil_configurado, fecha_creacion, logo_url, latitud, longitud) VALUES ((SELECT id FROM _seed_ids WHERE clave = 'U-D10'), 'Distribuidora Piriápolis', 'Distribuidora familiar de golosinas, snacks, galletitas y bebidas para kioscos, almacenes y cantinas escolares de Piriápolis y Pan de Azúcar. Atención personalizada y reparto semanal fijo por zona.', 'Piriápolis, Pan de Azúcar, Playa Hermosa, Playa Grande y Punta Colorada', 'Avenida Francisco Piria, Piriápolis, Maldonado', true, date_trunc('day', NOW()) - INTERVAL '182 days' + TIME '11:00', '/uploads/demo/logos/distribuidora-piriapolis.svg', -34.8622208, -55.2675493) RETURNING id) INSERT INTO _seed_ids SELECT 'D10', id FROM n;

